import json
comprobaciones = json.load(open("checks.json", encoding="utf-8"))
espacio = {"__name__": "generado"}
try:
    exec(compile(open("generated.py", encoding="utf-8").read(), "generated.py", "exec"), espacio)
    cargado = True
except BaseException:
    cargado = False
resultados = []
for c in comprobaciones:
    ok = False
    if cargado:
        try:
            valor = eval(c["expr"], espacio)
            ok = "raises" not in c and type(valor) is type(c["expected"]) and valor == c["expected"]
        except BaseException as exc:
            ok = type(exc).__name__ == c.get("raises")
    resultados.append(ok)
print("\n" + json.dumps(resultados))

